const DAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
let state;
let today;
// The day offset days from today, as YYYY-MM-DD with its weekday.
const dayAt = (offset) => {
  const [y, m, d] = today.split("-").map(Number);
  const at = new Date(Date.UTC(y, m - 1, d + offset));
  return { date: at.toISOString().slice(0, 10), weekday: at.getUTCDay() };
};
const render = () => {
  const ruled = new Set(state.data.rules.map((rule) => rule.weekday));
  // The next two weeks, kept off the weekdays the rules rule out.
  const freeDays = Array.from({ length: 14 }, (_, i) => dayAt(i)).filter(({ weekday }) => !ruled.has(weekday));
  document.getElementById("rules").replaceChildren(...state.data.rules.map((rule) => {
    const item = document.createElement("li");
    item.dataset.hook = "rule";
    item.textContent = "Never on " + DAYS[rule.weekday] + " ";
    const remove = document.createElement("button");
    remove.dataset.hook = "rule-remove";
    remove.textContent = "Remove";
    remove.addEventListener("click", () =>
      save([{ op: "remove", collection: "rules", id: rule.id, revisionCount: state.revisions.rules[rule.id] }]),
    );
    item.append(remove);
    return item;
  }));
  const sessions = [];
  if (freeDays.length > 0) {
    state.data.tasks.forEach((task, i) => {
      for (const step of [0, 3, 6]) {
        const day = freeDays[(i + step) % freeDays.length];
        const item = document.createElement("li");
        item.dataset.hook = "session";
        const time = document.createElement("time");
        time.dateTime = day.date + "T19:00";
        time.textContent = DAYS[day.weekday] + " " + day.date + ", 19:00";
        const name = document.createElement("span");
        name.dataset.hook = "session-task";
        name.textContent = task.name;
        item.append(time, " ", name);
        sessions.push(item);
      }
    });
  }
  document.getElementById("sessions").replaceChildren(...sessions);
};
const load = () => tessera.call("data.read").then((read) => { state = read; render(); });
const save = (operations) => tessera.call("data.patch", { operations }).then(load);
tessera.call("clock.now").then((now) => { today = now.date; return load(); });
document.querySelector("[data-hook=task-add]").addEventListener("click", () => {
  const name = document.querySelector("[data-hook=task-name]").value.trim();
  if (name) save([{ op: "add", collection: "tasks", record: { name } }]);
});
document.querySelector("[data-hook=rule-add]").addEventListener("click", () => {
  const weekday = Number(document.querySelector("[data-hook=rule-day]").value);
  if (!state.data.rules.some((rule) => rule.weekday === weekday)) save([{ op: "add", collection: "rules", record: { weekday } }]);
});

let state;
const render = () => {
  document.getElementById("cards").replaceChildren(...state.data.cards.map((card) => {
    const item = document.createElement("li");
    item.dataset.hook = "card";
    const front = document.createElement("strong");
    front.dataset.hook = "card-front";
    front.textContent = card.front;
    const back = document.createElement("span");
    back.dataset.hook = "card-back";
    back.textContent = card.back;
    item.append(front, " ", back);
    return item;
  }));
};
const load = () => tessera.call("data.read").then((read) => { state = read; render(); });
load();
// One card a line: its front before the first colon, its back after it.
const cardsOf = (notes) => notes.split(String.fromCharCode(10)).flatMap((line) => {
  const at = line.indexOf(":");
  if (at < 0) return [];
  const front = line.slice(0, at).trim();
  const back = line.slice(at + 1).trim();
  return front && back ? [{ front, back }] : [];
});
document.querySelector("[data-hook=cards-make]").addEventListener("click", () => {
  const field = document.querySelector("[data-hook=notes]");
  const made = cardsOf(field.value);
  if (made.length === 0) return;
  tessera.call("data.patch", { operations: made.map((record) => ({ op: "add", collection: "cards", record })) }).then(() => {
    field.value = "";
    return load();
  });
});
